/* ---------------- renderers ---------------- */

function blogLang() {
  return (typeof LANG !== 'undefined' && LANG === 'en') ? 'en' : 'bn';
}
function escHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function blogSeo(slug) {
  const a = BLOG[slug];
  if (!a) return null;
  const L = blogLang();
  return { title: a.title[L] + ' | BanglaTools', desc: a.desc[L] };
}

/* Blog index: grid of 15 article cards */
function renderBlogIndex() {
  const host = document.getElementById('blog-index');
  if (!host) return;
  const L = blogLang();
  const tt = (typeof t === 'function') ? t : function (k) { return k; };
  host.innerHTML = BLOG_ORDER.map(function (slug) {
    const a = BLOG[slug];
    const url = (typeof POST_URLS !== 'undefined' && POST_URLS[slug]) || '#/blog/' + slug;
    const art = (typeof BLOG_ART !== 'undefined' && BLOG_ART[slug]) || '';
    return '<a class="blog-card" href="' + url + '">' +
      '<span class="blog-banner" aria-hidden="true">' + art + '</span>' +
      '<span class="blog-card-title">' + escHtml(a.title[L]) + '</span>' +
      '<span class="blog-card-ex">' + escHtml(a.excerpt[L]) + '</span>' +
      '<span class="blog-more">' + escHtml(tt('blog.readMore')) + '</span>' +
      '</a>';
  }).join('');
  if (typeof initReveal === 'function') initReveal();
}

/* Single article view: semantic article + BlogPosting JSON-LD */
/* Related articles for interlinking (SEO) — 3 related posts per article */
const RELATED = {
  zakat: ['gold', 'income-tax', 'emi'],
  land: ['date', 'prayer', 'age'],
  electricity: ['emi', 'mess', 'income-tax'],
  gpa: ['age', 'bmi', 'date'],
  age: ['gpa', 'bmi', 'date'],
  gold: ['zakat', 'currency', 'income-tax'],
  'freelancer-tax': ['income-tax', 'currency', 'zakat'],
  prayer: ['date', 'land', 'qurbani'],
  emi: ['electricity', 'income-tax', 'currency'],
  currency: ['gold', 'freelancer-tax', 'emi'],
  bmi: ['age', 'gpa', 'mess'],
  date: ['age', 'prayer', 'land'],
  mess: ['electricity', 'emi', 'bmi'],
  qurbani: ['zakat', 'prayer', 'emi'],
  'income-tax': ['freelancer-tax', 'emi', 'zakat'],
  'zakat-nisab-2026': ['zakat', 'gold', 'income-tax'],
  'electricity-slab-2026': ['electricity', 'emi', 'mess'],
  'land-khatian-guide': ['land', 'date', 'prayer'],
  'gpa5-guide': ['gpa', 'age', 'bmi'],
  'emi-calculator-bd': ['emi', 'electricity', 'income-tax'],
  'gold-price-today-bd': ['gold', 'zakat', 'currency'],
  'dollar-rate-today-bd': ['currency', 'freelancer-tax', 'emi'],
  'prayer-times-dhaka': ['prayer', 'date', 'zakat'],
  'income-tax-slab-2026-27': ['income-tax', 'freelancer-tax', 'emi-calculator-bd'],
  'age-calculator-online': ['age', 'gpa', 'date'],
  'land-conversion-chart': ['land', 'land-khatian-guide', 'emi'],
  'electricity-bill-saving-tips': ['electricity', 'electricity-slab-2026', 'mess'],
  'freelancer-tax-return-guide': ['income-tax', 'freelancer-tax', 'emi'],
  'land-purchase-checklist': ['land', 'land-khatian-guide', 'land-conversion-chart'],
};

function renderRelated(slug, L) {
  var rel = RELATED[slug];
  if (!rel || !rel.length || typeof BLOG === 'undefined') return '';
  var items = rel.map(function (r) {
    var b = BLOG[r];
    if (!b) return '';
    var url = (typeof POST_URLS !== 'undefined' && POST_URLS[r]) || '#/blog/' + r;
    return '<li><a href="' + url + '">' + escHtml(b.title[L] || b.title.bn) + '</a></li>';
  }).join('');
  if (!items) return '';
  var heading = (L === 'en') ? 'Related articles' : 'সম্পর্কিত লেখা';
  return '<div class="related"><h2>' + heading + '</h2><ul>' + items + '</ul></div>';
}

function renderBlogArticle(slug) {
  const a = BLOG[slug];
  if (!a) return;
  const host = document.getElementById('blog-article');
  if (!host) return;
  const L = blogLang();
  const tt = (typeof t === 'function') ? t : function (k) { return k; };
  const steps = a.steps[L].map(function (s) { return '<li>' + escHtml(s) + '</li>'; }).join('');
  const tips = a.tips[L].map(function (s) { return '<li>' + escHtml(s) + '</li>'; }).join('');
  const faq = a.faq[L].map(function (f) {
    return '<div class="acc-item">' +
      '<button class="acc-head" onclick="toggleAcc(this)"><span>' + escHtml(f.q) + '</span><span class="acc-icon">+</span></button>' +
      '<div class="acc-body"><p>' + escHtml(f.a) + '</p></div>' +
      '</div>';
  }).join('');
  var sectionsHtml = '';
  if (a.sections && a.sections[L] && a.sections[L].length) {
    sectionsHtml = a.sections[L].map(function (s) {
      var paras = (s.p || []).map(function (p) { return '<p>' + escHtml(p) + '</p>'; }).join('');
      return '<h2>' + escHtml(s.h) + '</h2>' + paras;
    }).join('');
  }
  host.innerHTML =
    '<p class="crumb"><a href="#/blog">' + escHtml(tt('blog.back')) + '</a></p>' +
    '<article class="blog-article">' +
    '<h1>' + escHtml(a.title[L]) + '</h1>' +
    '<p class="lede">' + escHtml(a.excerpt[L]) + '</p>' +
    '<p>' + escHtml(a.intro[L]) + '</p>' +
    sectionsHtml +
    '<h2>' + escHtml(tt('blog.steps')) + '</h2>' +
    '<ol class="steps">' + steps + '</ol>' +
    '<h2>' + escHtml(tt('blog.tips')) + '</h2>' +
    '<ul class="tips">' + tips + '</ul>' +
    '<div class="blog-cta"><a class="btn" href="#/' + a.tool + '">' +
    escHtml(tt('blog.toolCta')) + ' — ' + escHtml(tt('tools.' + a.tool)) + '</a></div>' +
    '<div class="faq"><h2>' + escHtml(tt('blog.faqHead')) + '</h2>' +
    '<div class="accordion">' + faq + '</div></div>' +
    renderRelated(slug, L) +
    '</article>';
  injectArticleJsonLd(slug, L);
  if (typeof initReveal === 'function') initReveal();
}

/* ---------- Real post pages (Blogger item URLs) ----------
   Professional article renderer for post pages: the same markup/classes as
   the SPA article view (lede, steps, tips, CTA button, FAQ accordion), in
   either language. BLOG holds the full bilingual article data. */
function tL(key, L) {
  if (typeof I18N !== 'undefined') {
    if (I18N[L] && I18N[L][key] !== undefined) return I18N[L][key];
    if (I18N.bn && I18N.bn[key] !== undefined) return I18N.bn[key];
  }
  return key;
}
function renderPostArticle(slug, L) {
  var a = (typeof BLOG !== 'undefined') ? BLOG[slug] : null;
  if (!a) return '';
  L = (L === 'en') ? 'en' : 'bn';
  var steps = a.steps[L].map(function (s) { return '<li>' + escHtml(s) + '</li>'; }).join('');
  var tips = a.tips[L].map(function (s) { return '<li>' + escHtml(s) + '</li>'; }).join('');
  var faq = a.faq[L].map(function (f) {
    return '<div class="acc-item">' +
      '<button class="acc-head" type="button" onclick="toggleAcc(this)"><span>' + escHtml(f.q) + '</span><span class="acc-icon">+</span></button>' +
      '<div class="acc-body"><p>' + escHtml(f.a) + '</p></div>' +
      '</div>';
  }).join('');
  var toolName = tL('tools.' + a.tool, L);
  var home = 'https://banglatoolsbd.github.io';
  var sectionsHtml = '';
  if (a.sections && a.sections[L] && a.sections[L].length) {
    sectionsHtml = a.sections[L].map(function (s) {
      var paras = (s.p || []).map(function (p) { return '<p>' + escHtml(p) + '</p>'; }).join('');
      return '<h2>' + escHtml(s.h) + '</h2>' + paras;
    }).join('');
  }
  return '<h1 class="post-title">' + escHtml(a.title[L]) + '</h1>' +
    '<div class="post-body">' +
    '<p class="lede">' + escHtml(a.excerpt[L]) + '</p>' +
    '<p>' + escHtml(a.intro[L]) + '</p>' +
    sectionsHtml +
    '<h2>' + escHtml(tL('blog.steps', L)) + '</h2>' +
    '<ol class="steps">' + steps + '</ol>' +
    '<h2>' + escHtml(tL('blog.tips', L)) + '</h2>' +
    '<ul class="tips">' + tips + '</ul>' +
    '<div class="blog-cta"><a class="btn" href="' + home + '/#/' + a.tool + '">' +
    escHtml(tL('blog.toolCta', L)) + ' \u2014 ' + escHtml(toolName) + '</a></div>' +
    '<div class="faq"><h2>' + escHtml(tL('blog.faqHead', L)) + '</h2>' +
    '<div class="accordion">' + faq + '</div></div>' +
    renderRelated(slug, L) +
    '</div>';
}
/* Map a post URL back to its article slug */
function postSlugForUrl(url) {
  if (typeof POST_URLS === 'undefined') return null;
  url = String(url).split('#')[0].split('?')[0].replace(/\/$/, '');
  for (var k in POST_URLS) {
    if (POST_URLS[k].replace(/\/$/, '') === url) return k;
  }
  return null;
}

/* Per-article BlogPosting schema (replaced on each navigation) */
function injectArticleJsonLd(slug, L) {
  const olds = document.querySelectorAll('script[data-blog-ld]');
  for (let i = 0; i < olds.length; i++) olds[i].remove();
  const a = BLOG[slug];
  if (!a) return;
  const ld = {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: a.title[L],
    description: a.desc[L],
    inLanguage: L === 'bn' ? 'bn-BD' : 'en',
    author: { '@type': 'Organization', name: 'BanglaTools' },
    publisher: { '@type': 'Organization', name: 'BanglaTools' },
    datePublished: '2026-10-06',
    mainEntityOfPage: '#/blog/' + slug
  };
  const s = document.createElement('script');
  s.type = 'application/ld+json';
  s.setAttribute('data-blog-ld', '1');
  s.textContent = JSON.stringify(ld);
  document.head.appendChild(s);
}
